"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[89332],{31326:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"MobileStatusLogic","desc":"Pure open/close state machine for the phone status strip. No services and\\nno requires: the caller passes `MobileStatusConfig` (see\\ndocs/systems/mobile-status-hud.md).\\n\\nHolds (critical HP, fuel shortage, low stamina while sprinting) open the\\nstrip on their rising edge and keep it open while true. A hit opens it for\\n`HitOpenSeconds`. The strip closes at the latest pending close time, never\\nwhile a hold is true. A player collapse sticks until the next rising edge\\nor hit. Dead = hidden, and every hold is forgotten so revive re-opens.","source":{"line":15,"path":"src/ReplicatedStorage/SharedModules/MobileStatusLogic.luau"}}')}}]);